<!DOCTYPE html><html><head><meta charset="utf-8"><style>body{font-family:sans-serif;font-size:12px;color:#222}table{width:100%;border-collapse:collapse}th,td{border:1px solid #bbb;padding:6px;vertical-align:top}h1,h2{margin:0 0 8px} .meta{margin-bottom:12px}</style></head><body><h1><?= esc($title ?? 'Jadwal Tanding') ?></h1><div class="meta">Tanggal: <?= esc($jadwal->tanggal ?? '-') ?> | Arena: <?= esc($jadwal->nama_gelanggang ?? '-') ?> | Jam: <?= esc($jadwal->jam_mulai ?? '-') ?> - <?= esc($jadwal->jam_selesai ?? '-') ?></div><table><thead><tr><th>No. Partai</th><th>No. Pertandingan</th><th>Babak</th><th>Kelas</th><th>Merah</th><th>Biru</th><?php if (! empty($withScore)) : ?><th>Skor</th><?php endif; ?></tr></thead><tbody><?php foreach (($details ?? []) as $row) : ?><tr><td><?= esc((string) ($row->nomor_partai ?? '-')) ?></td><td><?= esc((string) ($row->nomor_pertandingan ?? '-')) ?></td><td><?= esc($row->babak ?? '-') ?></td><td><?= esc(($row->nama_kategori_lomba ?? '-') . ' / ' . ($row->nama_kelas ?? $row->label ?? '-')) ?></td><td><?= esc(($row->nama_atlet_merah ?? '-') . ' - ' . ($row->nama_kontingen_merah ?? '-')) ?></td><td><?= esc(($row->nama_atlet_biru ?? '-') . ' - ' . ($row->nama_kontingen_biru ?? '-')) ?></td><?php if (! empty($withScore)) : ?><td><?= esc((string) (($row->skor_merah ?? '-') . ' - ' . ($row->skor_biru ?? '-'))) ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></body></html>